"""Stage static public listing/support/privacy pages; does not deploy."""
from pathlib import Path
import shutil

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'appstore/site'
CSS = '''
:root{--paper:#f6f1e6;--ink:#292b24;--red:#c43b21;--quiet:#626456;--card:#fffaf1}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:17px/1.7 system-ui,sans-serif}main,header,footer{max-width:760px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;align-items:center}a{color:var(--red);text-underline-offset:5px}header .brand{font:italic 46px Georgia,serif;letter-spacing:-3px;color:var(--ink);text-decoration:none}nav{display:flex;gap:22px;font-size:14px}h1{font:italic 56px/1.08 Georgia,serif;letter-spacing:-2px;margin:24px 0}h2{font:27px/1.3 Georgia,serif;margin:32px 0 12px}.eyebrow{font:12px ui-monospace,monospace;letter-spacing:2px;text-transform:uppercase;color:var(--red)}.lead{font-size:21px;color:var(--quiet)}.strip{display:flex;justify-content:center;padding:44px 12px;font:38px ui-monospace,monospace;letter-spacing:9px}.piece{background:var(--red);color:var(--paper);padding:14px 12px;transform:rotate(-4deg);display:inline-block}.remain{padding:14px 12px;background:var(--card);border-top:1px dashed var(--quiet);border-bottom:1px dashed var(--quiet)}.panel{padding:26px;background:var(--card);border-radius:18px;margin:28px 0}footer{font-size:13px;color:var(--quiet);border-top:1px dashed #62645666}ul{padding-left:22px}li{margin:8px 0}.email{display:inline-block;padding:14px 20px;border-radius:12px;background:var(--ink);color:var(--paper);text-decoration:none;overflow-wrap:anywhere}a:focus-visible{outline:3px solid var(--red);outline-offset:5px}@media(max-width:500px){h1{font-size:42px}main,header,footer{padding:22px}nav{gap:14px}.strip{font-size:29px;letter-spacing:5px}}
'''
def page(title, canonical, content):
 return f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="SNIP, a small daily word game by HRLN interactive."><title>{title} | SNIP</title><link rel="canonical" href="https://snip.hrln-interactive.com{canonical}"><link rel="icon" href="/icon.png"><style>{CSS}</style></head><body><header><a class="brand" href="/" aria-label="SNIP home">snip.</a><nav aria-label="Main navigation"><a href="/support/">Support</a><a href="/privacy/">Privacy</a></nav></header><main>{content}</main><footer>2026 HRLN interactive · <a href="mailto:harlen.interactive@gmail.com">harlen.interactive@gmail.com</a></footer></body></html>'''
home = '''<p class="eyebrow">A small daily pleasure</p><h1>A little cut.<br>A little clever.</h1><p class="lead">Two clues. Two hidden words. One satisfying snip.</p><div class="strip" aria-label="PIRATE becomes PIE and RAT"><span class="remain">PIE</span><span class="piece">RAT</span></div><p>SNIP is a native iPhone word game that makes a little room for an aha. Cut a continuous word out of a bigger one, and the remaining letters make a second answer.</p><div class="panel"><h2>Your daily three</h2><p>Play three short puzzles in the same dated edition as everyone else, or explore four practice collections. There are no timers or lives. Hints and reveals are optional, and your receipt clearly records any help used.</p></div><p>Includes a 30-day rotation of 90 daily puzzles and 12 practice puzzles. Everything works offline, and your progress stays on your device.</p><p>No accounts, advertisements, subscriptions, or in-app purchases. Just warm paper, a crisp snip, and some good wordplay.</p><p>For iPhone with iOS 18 or later.</p><p><a href="/support/">Need a hand with your cuts?</a></p>'''
support = '''<p class="eyebrow">The little cut club</p><h1>A little help.</h1><p class="lead">Questions, feedback, or a puzzle that doesn't look right? We'd like to hear from you.</p><p><a class="email" href="mailto:harlen.interactive@gmail.com?subject=SNIP%20support">Email SNIP support</a></p><p>Contact: <a href="mailto:harlen.interactive@gmail.com">harlen.interactive@gmail.com</a><br>Publisher: HRLN interactive</p><h2>How do I select a piece?</h2><p>Drag across consecutive letters, or tap the first and last letter. The piece must come from inside the word. Both the cut-out and the letters left behind need at least three letters.</p><h2>What counts as a cut?</h2><p>A valid selection is counted when you tap Snip. Merely selecting or clearing letters costs nothing. A clean day means three first-try daily solves without hints or reveals.</p><h2>What do the receipt symbols mean?</h2><p>A number records your committed cuts for that word. An asterisk means a hint was used. A dash means the word was revealed; a reveal doesn't count as a solve.</p><h2>When does the daily change?</h2><p>At midnight UTC. Today shows a countdown in your local experience. Daily content is selected from a 30-day rotation stored in the app. If you're already playing at rollover, your current set remains available to finish.</p><h2>Can I play offline?</h2><p>Yes. Every included daily and practice puzzle is stored on your phone. No connection or account is needed.</p><h2>Where is my progress?</h2><p>It is saved on this device. Completed receipts appear in Your cuts. Replaying a practice collection keeps previous receipts. There is no cloud-sync account. Your operating system may include app data in your device backup.</p><h2>How do I change reminders or reset progress?</h2><p>Tap the gear in the studio. Sound, haptics, and reminders are optional. Reset my progress deletes saved results after confirmation. To change notification permission, use iPhone Settings.</p><h2>Reporting an issue</h2><p>Please include your iPhone model, iOS version, SNIP version, and what happened. For a puzzle issue, include the edition or practice collection. A screenshot is helpful; avoid sending personal or sensitive information.</p>'''
privacy = '''<p class="eyebrow">Updated 14 October 2026</p><h1>Your words stay<br>with you.</h1><p class="lead">Privacy policy for SNIP and its companion website, provided by HRLN interactive.</p><h2>The SNIP app</h2><p>SNIP does not collect or transmit your gameplay, device identifiers, or device information. It includes no accounts, advertisements, analytics SDKs, or tracking. It does not access your location, contacts, microphone, camera, or photo library.</p><h2>Local progress and preferences</h2><p>Your results, selected letters, practice sessions, and settings are saved locally on your device. The operating system may include app data in your device backup, according to your backup settings. Use Reset my progress in SNIP Settings to delete saved game results, or delete the app to remove its local data.</p><h2>Reminders and sharing</h2><p>Reminders are optional local notifications scheduled on your device. Permission is requested only when you choose to enable them. SNIP does not send remote notifications.</p><p>Sharing opens the iOS share sheet. The result image and text go only to the destination you choose; nothing is shared automatically. Other apps and websites apply their own privacy policies.</p><h2>Support email</h2><p>If you contact support, HRLN interactive receives your email address and the information you choose to include. We use this information to respond and handle your request. Please avoid sending sensitive information. You may request deletion of your support correspondence by contacting the address below, subject to any applicable recordkeeping requirements.</p><h2>This website</h2><p>These pages contain no analytics, advertising, tracking scripts, or forms. The website host may process basic connection information, such as IP addresses and browser-request details, to deliver and protect the site. Your email service handles messages you choose to send through an email link.</p><h2>Changes</h2><p>We will update this policy if the app's privacy practices change. The date above identifies the current version.</p><h2>Contact</h2><p>HRLN interactive<br><a href="mailto:harlen.interactive@gmail.com">harlen.interactive@gmail.com</a><br><a href="/support/">SNIP support</a></p>'''
for path, title, route, content in [('index.html','Daily word cuts','/',home),('support/index.html','Support','/support/',support),('privacy/index.html','Privacy policy','/privacy/',privacy)]:
 target=OUT/path;target.parent.mkdir(parents=True,exist_ok=True);target.write_text(page(title,route,content))
shutil.copy(ROOT/'appstore/icon/snip-1024.png',OUT/'icon.png')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://snip.hrln-interactive.com/sitemap.xml\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>https://snip.hrln-interactive.com{p}</loc></url>' for p in ['/','/support/','/privacy/'])+'</urlset>')
print('Staged homepage, support, privacy policy, and site icon. No hosting changes made.')
